Q: Print the following pattern for the given N number of rows A: <p>Change <code>cout &lt;&lt; &quot;4&quot;</code> to <code>cout &lt;&lt; n</code>:</p>
<pre class="lang-cpp prettyprint-override"><code>#include&lt;iostream&gt;
using namespace std;
int main(){ 
    int n; 
    cin&gt;&gt;n; 
    int i=1; 
    while(i&lt;=n){ 
        int j=1; 
        while(j&lt;=n){ 
            cout&lt;&lt;n; 
            j++; 
        } 
    cout&lt;&lt;endl; 
    i++;
    }
}

</code></pre>
<p>Sample Input <code>7</code>, Output:</p>
<pre><code>7
7777777
7777777
7777777
7777777
7777777
7777777
7777777
</code></pre>
